        let curLeft = 0;
        let curRight = colLen;

        for (let col = 0; col < colLen; col++) {
            if (matrix[row][col] === "1") {
                // compute height (can do this from either side)
                height[col]++;
                // compute left (from left to right)
                if (curLeft > left[col]) {
                    left[col] = curLeft;
                }
            } else {
                // compute height (can do this from either side)
                height[col] = 0;
                // compute left (from left to right)
                left[col] = 0;
                curLeft = col + 1;
            }

            // compute right (from right to left)
            const revCol = colLen - 1 - col;
            if (matrix[row][revCol] === "1") {
                if (curRight < right[revCol]) {
                    right[revCol] = curRight;
                }
            } else {
                right[revCol] = colLen;
                curRight = revCol;
            }
        }

        // compute the area of rectangle (can do this from either side)
        for (let col = 0; col < colLen; col++) {
            const area = (right[col] - left[col]) * height[col];
            if (area > maxSeen) {
                maxSeen = area;
            }
        }
    }

    return maxSeen;
};

